// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp, uint256 initialBalance) public {
        // Bound blockNumber to a reasonable range and ensure block.number % 15 == 0
        blockNumber = bound(blockNumber, 1, 100000);
        vm.assume(blockNumber % 15 == 0);

        // Ensure block.timestamp > pastBlockTime (initially 0)
        blockTimestamp = bound(blockTimestamp, 1, 1000000);

        // Set up initial balance for the contract (at least 10 ether to allow the transfer)
        vm.deal(address(c), 10 ether + initialBalance % 1 ether);

        uint256 balanceBefore = address(c).balance;

        // Perform the fallback call with 10 ether, setting block.number and block.timestamp
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            uint256 balanceAfter = address(c).balance;
            // The rule: balance must have decreased because the transfer happened
            assertTrue(balanceAfter < balanceBefore, "Balance should decrease after fallback when block.number % 15 == 0");
        }
    }
}

